-- PAWGLOW Manufacturing Suite Database Schema
-- Migration for Material Categories, Materials, Formulas, and Products Management

-- Create material_type enum
create type "public"."material_type" as enum ('raw_material', 'packaging', 'label');

-- Create unit_type enum
create type "public"."unit_type" as enum ('kg', 'g', 'l', 'ml', 'units', 'meters', 'cm');

-- Material Categories Table
create table "public"."material_categories" (
    "id" uuid generated by default as uuid primary key,
    "name" text not null,
    "prefix" text not null unique,
    "description" text,
    "tenant_id" text not null default requesting_user_id(),
    "created_at" timestamp with time zone default timezone('utc'::text, now()),
    "updated_at" timestamp with time zone default timezone('utc'::text, now())
);

-- Materials Table  
create table "public"."materials" (
    "id" uuid generated by default as uuid primary key,
    "category_id" uuid not null references "public"."material_categories"("id") on delete restrict,
    "name" text not null,
    "code" text not null unique,
    "description" text,
    "cost_per_unit" numeric(10,4) not null check (cost_per_unit >= 0),
    "unit_type" unit_type not null,
    "material_type" material_type not null,
    "supplier" text,
    "min_stock_level" numeric(10,4) default 0 check (min_stock_level >= 0),
    "current_stock" numeric(10,4) default 0 check (current_stock >= 0),
    "tenant_id" text not null default requesting_user_id(),
    "created_at" timestamp with time zone default timezone('utc'::text, now()),
    "updated_at" timestamp with time zone default timezone('utc'::text, now())
);

-- Formulas Table
create table "public"."formulas" (
    "id" uuid generated by default as uuid primary key,
    "name" text not null,
    "description" text,
    "created_by" text not null,
    "tenant_id" text not null default requesting_user_id(),
    "created_at" timestamp with time zone default timezone('utc'::text, now()),
    "updated_at" timestamp with time zone default timezone('utc'::text, now())
);

-- Formula Versions Table
create table "public"."formula_versions" (
    "id" uuid generated by default as uuid primary key,
    "formula_id" uuid not null references "public"."formulas"("id") on delete cascade,
    "version_number" integer not null,
    "is_active" boolean default false,
    "notes" text,
    "created_by" text not null,
    "tenant_id" text not null default requesting_user_id(),
    "created_at" timestamp with time zone default timezone('utc'::text, now()),
    unique(formula_id, version_number)
);

-- Formula Ingredients Table
create table "public"."formula_ingredients" (
    "id" uuid generated by default as uuid primary key,
    "formula_version_id" uuid not null references "public"."formula_versions"("id") on delete cascade,
    "material_id" uuid not null references "public"."materials"("id") on delete restrict,
    "percentage" numeric(5,2) not null check (percentage > 0 and percentage <= 100),
    "tenant_id" text not null default requesting_user_id(),
    "created_at" timestamp with time zone default timezone('utc'::text, now()),
    unique(formula_version_id, material_id)
);

-- Manufacturing Products Table (named to avoid conflict with Stripe products)
create table "public"."manufacturing_products" (
    "id" uuid generated by default as uuid primary key,
    "name" text not null,
    "description" text,
    "sku" text unique,
    "formula_version_id" uuid references "public"."formula_versions"("id") on delete set null,
    "packaging_material_id" uuid references "public"."materials"("id") on delete set null,
    "label_material_id" uuid references "public"."materials"("id") on delete set null,
    "net_weight" numeric(10,4) not null check (net_weight > 0),
    "net_weight_unit" unit_type not null default 'g',
    "cogs" numeric(10,4) check (cogs >= 0),
    "selling_price" numeric(10,4) check (selling_price >= 0),
    "status" text default 'draft' check (status in ('draft', 'active', 'discontinued')),
    "tenant_id" text not null default requesting_user_id(),
    "created_at" timestamp with time zone default timezone('utc'::text, now()),
    "updated_at" timestamp with time zone default timezone('utc'::text, now())
);

-- Create indexes for performance optimization
create index "idx_material_categories_tenant" on "public"."material_categories"("tenant_id");
create index "idx_material_categories_prefix" on "public"."material_categories"("prefix");
create index "idx_materials_tenant" on "public"."materials"("tenant_id");
create index "idx_materials_category" on "public"."materials"("category_id");
create index "idx_materials_code" on "public"."materials"("code");
create index "idx_materials_type" on "public"."materials"("material_type");
create index "idx_formulas_tenant" on "public"."formulas"("tenant_id");
create index "idx_formula_versions_formula" on "public"."formula_versions"("formula_id");
create index "idx_formula_versions_active" on "public"."formula_versions"("is_active");
create index "idx_formula_ingredients_version" on "public"."formula_ingredients"("formula_version_id");
create index "idx_formula_ingredients_material" on "public"."formula_ingredients"("material_id");
create index "idx_manufacturing_products_tenant" on "public"."manufacturing_products"("tenant_id");
create index "idx_manufacturing_products_formula" on "public"."manufacturing_products"("formula_version_id");
create index "idx_manufacturing_products_packaging" on "public"."manufacturing_products"("packaging_material_id");
create index "idx_manufacturing_products_label" on "public"."manufacturing_products"("label_material_id");
create index "idx_manufacturing_products_sku" on "public"."manufacturing_products"("sku");

-- Enable Row Level Security
alter table "public"."material_categories" enable row level security;
alter table "public"."materials" enable row level security;
alter table "public"."formulas" enable row level security;
alter table "public"."formula_versions" enable row level security;
alter table "public"."formula_ingredients" enable row level security;
alter table "public"."manufacturing_products" enable row level security;

