-- Function to generate next material code
CREATE OR REPLACE FUNCTION generate_material_code(p_category_prefix text)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_next_number integer;
    v_code text;
BEGIN
    -- Get the next number for this category prefix
    SELECT COALESCE(MAX(CAST(SUBSTRING(code, LENGTH(p_category_prefix) + 1) AS integer)), 0) + 1
    INTO v_next_number
    FROM materials
    WHERE code LIKE p_category_prefix || '%'
    AND tenant_id = requesting_user_id();
    
    -- Generate the new code
    v_code := p_category_prefix || LPAD(v_next_number::text, 3, '0');
    
    RETURN v_code;
END;
$$;

-- Function to validate formula ingredient percentages
CREATE OR REPLACE FUNCTION validate_formula_percentages(p_formula_version_id uuid)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_total_percentage numeric;
BEGIN
    SELECT COALESCE(SUM(percentage), 0)
    INTO v_total_percentage
    FROM formula_ingredients
    WHERE formula_version_id = p_formula_version_id;
    
    RETURN v_total_percentage = 100;
END;
$$;

-- Function to calculate COGS for a manufacturing product
CREATE OR REPLACE FUNCTION calculate_product_cogs(p_product_id uuid)
RETURNS numeric(10,4)
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_product RECORD;
    v_total_cost numeric(10,4) := 0;
    v_ingredient_cost numeric(10,4);
BEGIN
    -- Get product details
    SELECT * INTO v_product
    FROM manufacturing_products
    WHERE id = p_product_id
    AND tenant_id = requesting_user_id();
    
    IF NOT FOUND THEN
        RETURN NULL;
    END IF;
    
    -- Calculate ingredient costs if formula is set
    IF v_product.formula_version_id IS NOT NULL THEN
        SELECT SUM(fi.percentage / 100 * 
                  (m.cost_per_unit * 
                   CASE 
                       WHEN v_product.net_weight_unit = 'g' AND m.unit_type = 'kg' THEN v_product.net_weight / 1000
                       WHEN v_product.net_weight_unit = 'kg' AND m.unit_type = 'g' THEN v_product.net_weight * 1000
                       WHEN v_product.net_weight_unit = 'ml' AND m.unit_type = 'l' THEN v_product.net_weight / 1000
                       WHEN v_product.net_weight_unit = 'l' AND m.unit_type = 'ml' THEN v_product.net_weight * 1000
                       ELSE v_product.net_weight
                   END))
        INTO v_ingredient_cost
        FROM formula_ingredients fi
        JOIN materials m ON fi.material_id = m.id
        WHERE fi.formula_version_id = v_product.formula_version_id;
        
        v_total_cost := COALESCE(v_ingredient_cost, 0);
    END IF;
    
    -- Add packaging cost
    IF v_product.packaging_material_id IS NOT NULL THEN
        SELECT cost_per_unit
        INTO v_ingredient_cost
        FROM materials
        WHERE id = v_product.packaging_material_id
        AND tenant_id = requesting_user_id();
        
        v_total_cost := v_total_cost + COALESCE(v_ingredient_cost, 0);
    END IF;
    
    -- Add label cost
    IF v_product.label_material_id IS NOT NULL THEN
        SELECT cost_per_unit
        INTO v_ingredient_cost
        FROM materials
        WHERE id = v_product.label_material_id
        AND tenant_id = requesting_user_id();
        
        v_total_cost := v_total_cost + COALESCE(v_ingredient_cost, 0);
    END IF;
    
    RETURN v_total_cost;
END;
$$;

-- Trigger to automatically update updated_at columns
CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    NEW.updated_at = timezone('utc'::text, now());
    RETURN NEW;
END;
$$;

-- Create triggers for updated_at
CREATE TRIGGER update_material_categories_updated_at
    BEFORE UPDATE ON material_categories
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER update_materials_updated_at
    BEFORE UPDATE ON materials
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER update_formulas_updated_at
    BEFORE UPDATE ON formulas
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER update_manufacturing_products_updated_at
    BEFORE UPDATE ON manufacturing_products
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

-- Grant permissions to authenticated users
GRANT ALL ON material_categories TO authenticated;
GRANT ALL ON materials TO authenticated;
GRANT ALL ON formulas TO authenticated;
GRANT ALL ON formula_versions TO authenticated;
GRANT ALL ON formula_ingredients TO authenticated;
GRANT ALL ON manufacturing_products TO authenticated;

-- Grant usage permissions for the functions
GRANT EXECUTE ON FUNCTION generate_material_code(text) TO authenticated;
GRANT EXECUTE ON FUNCTION validate_formula_percentages(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION calculate_product_cogs(uuid) TO authenticated;